using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;

namespace VfxKit
{
    /// <summary>
    /// One scene for every VFX of the library. A basic runtime UI (built by code, uGUI) switches between effects:
    /// list on the left (grouped by category), Prev / Replay / Next, Loop, camera presets, time speed, 2 m reference.
    /// Keys: Left / Right = previous / next, Space = replay, 1 / 2 / 3 = camera, R = reference, L = loop, mouse wheel = zoom.
    /// The scene is generated by the editor menu VFX / Showcase / Build Scene (VfxShowcaseBuild) from every Assets/VFX/*/Prefabs/VFX_*.prefab.
    /// </summary>
    public class VfxShowcase : MonoBehaviour
    {
        [Serializable]
        public class Entry { public string name; public string category; public GameObject prefab; }

        public List<Entry> entries = new List<Entry>();
        public Camera cam;
        public bool loop = true;
        public float loopGap = 0.8f;

        // camera presets: elevation angle (deg) and distance; art lead default is a 3/4 view from 40 deg, top-down 60 deg for slash / ground effects
        static readonly (string label, float angle, float dist)[] Presets =
        {
            ("Top-down 60°", 60f, 9f), ("3/4 40°", 40f, 9f), ("Side 8°", 8f, 9f),
        };

        int index = -1, preset;
        GameObject current, reference, ground;
        float age, endTime;
        bool loops;
        float camDistance = 9f, camAngle = 60f;
        readonly Vector3 camTarget = new Vector3(0f, 1.1f, 0f);

        Text title, subtitle, loopLabel, refLabel, speedLabel;
        readonly List<Image> rows = new List<Image>();
        Canvas canvas;
        bool built;

        void Awake() => Build();

        void Start()
        {
            if (entries.Count > 0 && index < 0) Select(0);
        }

        // ------------------------------------------------------------------ scene

        public void Build()
        {
            if (built) return;
            built = true;
            if (cam == null) cam = Camera.main;
            if (cam != null)
            {
                cam.clearFlags = CameraClearFlags.SolidColor;
                cam.backgroundColor = new Color(0.07f, 0.08f, 0.1f);
                cam.fieldOfView = 40f;
            }
            BuildStage();
            BuildUI();
            SetPreset(0, true);
        }

        void BuildStage()
        {
            var unlitColor = Shader.Find("Universal Render Pipeline/Unlit") != null && VfxKitPipeline.IsUrp ? Shader.Find("Universal Render Pipeline/Unlit") : Shader.Find("Unlit/Color");
            ground = GameObject.CreatePrimitive(PrimitiveType.Plane);
            ground.name = "Ground";
            ground.transform.SetParent(transform, false);
            ground.transform.localScale = new Vector3(3f, 1f, 3f);
            Destroy(ground.GetComponent<Collider>());
            var gm = new Material(Shader.Find("Unlit/Texture") ?? unlitColor);
            gm.mainTexture = GridTexture();
            gm.mainTextureScale = new Vector2(30f, 30f);
            ground.GetComponent<Renderer>().sharedMaterial = gm;

            reference = GameObject.CreatePrimitive(PrimitiveType.Capsule);   // 2 m tall, the scale reference for the whole library
            reference.name = "Reference_2m";
            reference.transform.SetParent(transform, false);
            reference.transform.localPosition = new Vector3(-2.2f, 1f, -1.2f);
            Destroy(reference.GetComponent<Collider>());
            var rm = new Material(unlitColor); rm.color = new Color(0.35f, 0.38f, 0.44f);
            reference.GetComponent<Renderer>().sharedMaterial = rm;
            reference.SetActive(true);
        }

        static Texture2D GridTexture()
        {
            const int n = 64;
            var t = new Texture2D(n, n, TextureFormat.RGB24, true) { wrapMode = TextureWrapMode.Repeat, filterMode = FilterMode.Bilinear };
            var bg = new Color(0.11f, 0.12f, 0.145f); var line = new Color(0.2f, 0.22f, 0.27f);
            for (int y = 0; y < n; y++)
                for (int x = 0; x < n; x++) t.SetPixel(x, y, (x == 0 || y == 0) ? line : bg);
            t.Apply();
            return t;
        }

        // ------------------------------------------------------------------ selection

        public void Select(int i)
        {
            if (entries.Count == 0) return;
            index = (i % entries.Count + entries.Count) % entries.Count;
            Spawn();
            for (int k = 0; k < rows.Count; k++) rows[k].color = k == index ? new Color(0.2f, 0.45f, 0.75f, 0.95f) : new Color(0.16f, 0.18f, 0.22f, 0.9f);
        }

        public void Replay() { if (index >= 0) Spawn(); }

        void Spawn()
        {
            if (current != null) Destroy(current);
            var e = entries[index];
            if (e.prefab == null) return;
            current = Instantiate(e.prefab, Vector3.zero, Quaternion.identity, transform);
            current.name = e.prefab.name;
            age = 0f;
            endTime = EstimateDuration(current, out loops);
            if (title != null) title.text = e.name;
            if (subtitle != null) subtitle.text = e.category + "   ·   " + (index + 1) + " / " + entries.Count + (loops ? "   ·   looping effect" : "   ·   " + endTime.ToString("0.0") + " s");
        }

        // upper bound of the effect length: delay + duration + longest particle life, divided by the simulation speed
        static float EstimateDuration(GameObject go, out bool looping)
        {
            looping = false;
            float end = 0f;
            foreach (var ps in go.GetComponentsInChildren<ParticleSystem>(true))
            {
                var m = ps.main;
                if (m.loop) looping = true;
                float speed = Mathf.Max(0.01f, m.simulationSpeed);
                end = Mathf.Max(end, (m.startDelay.constantMax + (m.loop ? 0f : m.duration) + m.startLifetime.constantMax) / speed);
            }
            return Mathf.Clamp(end, 0.6f, 7f);
        }

        // ------------------------------------------------------------------ update

        void Update()
        {
            if (current != null)
            {
                age += Time.deltaTime;
                if (loop && !loops && age > endTime + loopGap) Replay();
            }
            HandleKeys();
            UpdateCamera(Time.unscaledDeltaTime);
        }

        void HandleKeys()
        {
            if (Input.GetKeyDown(KeyCode.RightArrow) || Input.GetKeyDown(KeyCode.D)) Select(index + 1);
            if (Input.GetKeyDown(KeyCode.LeftArrow) || Input.GetKeyDown(KeyCode.A)) Select(index - 1);
            if (Input.GetKeyDown(KeyCode.Space)) Replay();
            if (Input.GetKeyDown(KeyCode.Alpha1)) SetPreset(0, false);
            if (Input.GetKeyDown(KeyCode.Alpha2)) SetPreset(1, false);
            if (Input.GetKeyDown(KeyCode.Alpha3)) SetPreset(2, false);
            if (Input.GetKeyDown(KeyCode.R)) ToggleReference();
            if (Input.GetKeyDown(KeyCode.L)) ToggleLoop();
            float wheel = Input.mouseScrollDelta.y;
            if (Mathf.Abs(wheel) > 0.01f && !EventSystem.current.IsPointerOverGameObject()) camDistance = Mathf.Clamp(camDistance - wheel * 0.8f, 3f, 25f);
        }

        void UpdateCamera(float dt)
        {
            if (cam == null) return;
            float a = camAngle * Mathf.Deg2Rad;
            var want = camTarget + new Vector3(0f, Mathf.Sin(a), -Mathf.Cos(a)) * camDistance;
            float k = 1f - Mathf.Exp(-8f * dt);
            cam.transform.position = Vector3.Lerp(cam.transform.position, want, k);
            cam.transform.rotation = Quaternion.Slerp(cam.transform.rotation, Quaternion.LookRotation(camTarget - cam.transform.position), k);
        }

        void SetPreset(int i, bool snap)
        {
            preset = i;
            camAngle = Presets[i].angle; camDistance = Presets[i].dist;
            if (snap && cam != null)
            {
                float a = camAngle * Mathf.Deg2Rad;
                cam.transform.position = camTarget + new Vector3(0f, Mathf.Sin(a), -Mathf.Cos(a)) * camDistance;
                cam.transform.rotation = Quaternion.LookRotation(camTarget - cam.transform.position);
            }
        }

        void ToggleReference() { reference.SetActive(!reference.activeSelf); if (refLabel) refLabel.text = "2 m ref: " + (reference.activeSelf ? "ON" : "OFF"); }
        void ToggleLoop() { loop = !loop; if (loopLabel) loopLabel.text = "Loop: " + (loop ? "ON" : "OFF"); }

        void CycleSpeed()
        {
            float[] s = { 1f, 0.5f, 0.25f, 0.1f };
            int i = Array.IndexOf(s, Mathf.Round(Time.timeScale * 100f) / 100f);
            Time.timeScale = s[(i + 1) % s.Length];
            if (speedLabel) speedLabel.text = "Speed: " + Time.timeScale.ToString("0.##") + "×";
        }

        void OnDestroy() { Time.timeScale = 1f; }

        // ------------------------------------------------------------------ UI (uGUI built by code)

        static Font font;
        static readonly Color PanelColor = new Color(0.08f, 0.09f, 0.12f, 0.88f);

        void BuildUI()
        {
            if (FindObjectOfType<EventSystem>() == null)
                new GameObject("EventSystem", typeof(EventSystem), typeof(StandaloneInputModule));
            font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");

            var cgo = new GameObject("ShowcaseUI", typeof(Canvas), typeof(CanvasScaler), typeof(GraphicRaycaster));
            cgo.transform.SetParent(transform, false);
            canvas = cgo.GetComponent<Canvas>();
            canvas.renderMode = RenderMode.ScreenSpaceOverlay;
            var scaler = cgo.GetComponent<CanvasScaler>();
            scaler.uiScaleMode = CanvasScaler.ScaleMode.ScaleWithScreenSize;
            scaler.referenceResolution = new Vector2(1280f, 720f);
            scaler.matchWidthOrHeight = 0.5f;

            // left panel: header + scrolling list
            var left = Panel("List", cgo.transform, PanelColor);
            Anchor(left, new Vector2(0, 0), new Vector2(0, 1), new Vector2(0, 0), new Vector2(270, 0), new Vector2(0, 0.5f));
            var head = Label("Header", left, "VFX SHOWCASE", 20, TextAnchor.MiddleLeft, Color.white);
            Anchor(head.rectTransform, new Vector2(0, 1), new Vector2(1, 1), new Vector2(14, -50), new Vector2(-10, -6), new Vector2(0.5f, 1));
            var scroll = new GameObject("Scroll", typeof(RectTransform), typeof(ScrollRect), typeof(Image));
            scroll.transform.SetParent(left, false);
            var srt = (RectTransform)scroll.transform;
            Anchor(srt, Vector2.zero, Vector2.one, new Vector2(6, 8), new Vector2(-6, -56), new Vector2(0.5f, 0.5f));
            scroll.GetComponent<Image>().color = new Color(0, 0, 0, 0.15f);
            var viewport = new GameObject("Viewport", typeof(RectTransform), typeof(RectMask2D));
            viewport.transform.SetParent(scroll.transform, false);
            Anchor((RectTransform)viewport.transform, Vector2.zero, Vector2.one, Vector2.zero, Vector2.zero, new Vector2(0, 1));
            var content = new GameObject("Content", typeof(RectTransform), typeof(VerticalLayoutGroup), typeof(ContentSizeFitter));
            content.transform.SetParent(viewport.transform, false);
            var crt = (RectTransform)content.transform;
            crt.pivot = new Vector2(0.5f, 1); crt.anchorMin = new Vector2(0, 1); crt.anchorMax = new Vector2(1, 1); crt.anchoredPosition = Vector2.zero; crt.sizeDelta = Vector2.zero;
            var vlg = content.GetComponent<VerticalLayoutGroup>();
            vlg.spacing = 3; vlg.padding = new RectOffset(4, 4, 4, 4); vlg.childControlHeight = true; vlg.childControlWidth = true; vlg.childForceExpandHeight = false;
            content.GetComponent<ContentSizeFitter>().verticalFit = ContentSizeFitter.FitMode.PreferredSize;
            var sr = scroll.GetComponent<ScrollRect>();
            sr.viewport = (RectTransform)viewport.transform; sr.content = crt; sr.horizontal = false; sr.scrollSensitivity = 30f;

            string lastCat = null;
            rows.Clear();
            for (int i = 0; i < entries.Count; i++)
            {
                var e = entries[i];
                if (e.category != lastCat)
                {
                    lastCat = e.category;
                    var cat = Label("Cat_" + e.category, crt, e.category.ToUpperInvariant(), 12, TextAnchor.MiddleLeft, new Color(0.55f, 0.7f, 0.9f));
                    cat.gameObject.AddComponent<LayoutElement>().preferredHeight = 24;
                }
                int idx = i;
                var b = Button(e.name, crt, () => Select(idx), 15);
                b.gameObject.AddComponent<LayoutElement>().preferredHeight = 30;
                rows.Add(b.GetComponent<Image>());
            }

            // title (top centre)
            var tp = Panel("Title", cgo.transform, new Color(0.08f, 0.09f, 0.12f, 0.6f));
            Anchor(tp, new Vector2(0.5f, 1), new Vector2(0.5f, 1), new Vector2(-250, -64), new Vector2(250, -10), new Vector2(0.5f, 1));
            tp.offsetMin = new Vector2(-250 + 135, -64); tp.offsetMax = new Vector2(250 + 135, -10);
            title = Label("Name", tp, "", 24, TextAnchor.UpperCenter, Color.white);
            Anchor(title.rectTransform, Vector2.zero, Vector2.one, new Vector2(6, 0), new Vector2(-6, -4), new Vector2(0.5f, 0.5f));
            subtitle = Label("Info", tp, "", 13, TextAnchor.LowerCenter, new Color(0.7f, 0.78f, 0.9f));
            Anchor(subtitle.rectTransform, Vector2.zero, Vector2.one, new Vector2(6, 4), new Vector2(-6, 0), new Vector2(0.5f, 0.5f));

            // bottom bar
            var bar = Panel("Bar", cgo.transform, PanelColor);
            Anchor(bar, new Vector2(0, 0), new Vector2(1, 0), new Vector2(280, 8), new Vector2(-8, 62), new Vector2(0.5f, 0));
            var h = bar.gameObject.AddComponent<HorizontalLayoutGroup>();
            h.spacing = 6; h.padding = new RectOffset(8, 8, 8, 8); h.childControlWidth = true; h.childControlHeight = true; h.childForceExpandWidth = true;
            Button("◀  Prev", bar, () => Select(index - 1), 15);
            Button("Replay (Space)", bar, Replay, 15);
            Button("Next  ▶", bar, () => Select(index + 1), 15);
            loopLabel = ButtonLabel(Button("Loop: ON", bar, ToggleLoop, 14));
            speedLabel = ButtonLabel(Button("Speed: 1×", bar, CycleSpeed, 14));
            refLabel = ButtonLabel(Button("2 m ref: ON", bar, ToggleReference, 14));
            for (int i = 0; i < Presets.Length; i++) { int p = i; Button(Presets[i].label, bar, () => SetPreset(p, false), 13); }

            var hint = Label("Hint", cgo.transform, "← → switch   Space replay   1·2·3 camera   R reference   L loop   wheel zoom", 12, TextAnchor.LowerRight, new Color(0.6f, 0.65f, 0.75f));
            Anchor(hint.rectTransform, new Vector2(0, 0), new Vector2(1, 0), new Vector2(280, 68), new Vector2(-12, 90), new Vector2(0.5f, 0));
        }

        static RectTransform Panel(string name, Transform parent, Color c)
        {
            var go = new GameObject(name, typeof(RectTransform), typeof(Image));
            go.transform.SetParent(parent, false);
            go.GetComponent<Image>().color = c;
            return (RectTransform)go.transform;
        }

        static void Anchor(RectTransform r, Vector2 min, Vector2 max, Vector2 offMin, Vector2 offMax, Vector2 pivot)
        {
            r.pivot = pivot;   // pivot first: changing it afterwards would shift the rect
            r.anchorMin = min; r.anchorMax = max; r.offsetMin = offMin; r.offsetMax = offMax;
        }

        static Text Label(string name, Transform parent, string text, int size, TextAnchor anchor, Color color)
        {
            var go = new GameObject(name, typeof(RectTransform), typeof(Text));
            go.transform.SetParent(parent, false);
            var t = go.GetComponent<Text>();
            t.font = font; t.text = text; t.fontSize = size; t.alignment = anchor; t.color = color; t.raycastTarget = false;
            t.horizontalOverflow = HorizontalWrapMode.Wrap; t.verticalOverflow = VerticalWrapMode.Overflow;
            return t;
        }

        static UnityEngine.UI.Button Button(string label, Transform parent, UnityEngine.Events.UnityAction onClick, int size)
        {
            var go = new GameObject("Btn_" + label, typeof(RectTransform), typeof(Image), typeof(UnityEngine.UI.Button));
            go.transform.SetParent(parent, false);
            var img = go.GetComponent<Image>(); img.color = new Color(0.16f, 0.18f, 0.22f, 0.9f);
            var b = go.GetComponent<UnityEngine.UI.Button>();
            var colors = b.colors; colors.highlightedColor = new Color(1.25f, 1.25f, 1.25f); colors.pressedColor = new Color(0.8f, 0.8f, 0.8f); b.colors = colors;
            b.targetGraphic = img;
            b.onClick.AddListener(onClick);
            var t = Label("Text", go.transform, label, size, TextAnchor.MiddleCenter, Color.white);
            Anchor(t.rectTransform, Vector2.zero, Vector2.one, new Vector2(6, 0), new Vector2(-6, 0), new Vector2(0.5f, 0.5f));
            return b;
        }

        static Text ButtonLabel(UnityEngine.UI.Button b) => b.GetComponentInChildren<Text>();

#if UNITY_EDITOR
        /// <summary>Edit-mode helpers used by VfxShowcaseBuild to check the scene without entering Play mode.</summary>
        public void EditorSelect(int i, float simulateTo)
        {
            Build();
            Select(i);
            foreach (var ps in current.GetComponentsInChildren<ParticleSystem>(true))
                if (ps.transform.parent == null || ps.transform.parent.GetComponentInParent<ParticleSystem>() == null)
                    ps.Simulate(simulateTo, true, true);
        }

        public void EditorSnapCamera() => SetPreset(preset, true);
        public Canvas EditorCanvas => canvas;
#endif
    }

    static class VfxKitPipeline
    {
        public static bool IsUrp
        {
            get
            {
                var rp = UnityEngine.Rendering.GraphicsSettings.currentRenderPipeline;
                return rp != null && rp.GetType().FullName.Contains("Universal");
            }
        }
    }
}
